  real<lower=0> sigmam;
  real<lower=0> sigmae;
  vector[nM] m;
  real alpha;
}
model {
  sigmam ~ normal(0, 1);
  sigmae ~ normal(0, 1);
  m ~ normal(0, sigmam);
  alpha ~ normal(0, 3.16);
  ys ~ normal(alpha + Ws * m, sigmae);
}

--- Model C ---

